private fun materialIcon(name: String, autoMirror: Boolean, pathData: String): ImageVector =
    ImageVector.Builder(
        name = "Filled.$name",
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
        autoMirror = autoMirror,
    ).addPath(pathData = addPathNodes(pathData), fill = SolidColor(Color.Black)).build()
